#include "app/recovery.h"
#include <sqlite3.h>
#include <fstream>
#include <iostream>
#include <stdexcept>
using namespace roots::gui;namespace s=storage;namespace a=app;
namespace {
int checks{};
constexpr std::string_view Password="Synthetic interrupted conversion password";
void Check(bool ok,const char* label){++checks;if(!ok)throw std::runtime_error(label);}
template<class T>T Take(s::Result<T> r){if(!r)throw std::runtime_error(s::ErrorName(r.error));return std::move(*r.value);}
std::string Bytes(const std::filesystem::path& p){std::ifstream f(p,std::ios::binary);return {std::istreambuf_iterator<char>(f),{}};}
s::Scope Scope(){return {"conversion-backend",{*Hash256::Parse(std::string(64,'1'))},"wallet/札幌"};}
s::Metadata Metadata(bool other=false){s::Metadata m;m.revision=1;m.display_name=other?"Other metadata":"Protected metadata";m.labels={{{s::TargetKind::Address,"public-address"},"Independent label"}};m.layouts={{"history","date",true}};m.widths={{"history","amount",173}};m.freezes={{s::TargetKind::Output,std::string(64,'a')+":7"}};m.drafts={{"draft",{9007199254740999ULL},"Independent draft",Money::Satoshis(-9223372036854775807LL)}};return m;}
a::DocumentRegistry Docs(bool other=false){a::DocumentRegistry d;auto g=Scope().network;const auto id=d.OpenWallet("Wallet A",{*BackendSessionId::Make("backend-A"),*WalletId::Make("wallet-A"),g},false);auto& one=*d.Find(id);one.sections[1].note.SetDraft(other?"Other public draft":"Protected public draft");one.sections[1].scroll_y=127;one.draft_revision={9007199254740999ULL};one.selected_coins={{*Hash256::Parse(std::string(64,'a')),7}};one.excluded_coins={{*Hash256::Parse(std::string(64,'b')),8}};d.OpenWallet("Wallet B",{*BackendSessionId::Make("backend-B"),*WalletId::Make("wallet-B"),g},false);d.OpenTransaction("Transaction A");d.OpenTransaction("Transaction B");d.Activate(id);return d;}
void Seed(const std::filesystem::path& p){auto store=Take(s::MetadataStore::Open(p));auto m=Metadata();m.revision=0;Take(store->Save(Scope(),m));s::Workspace w;w.restore_documents=true;w.preferences.hide_balances=true;Take(store->SaveWorkspace(w));s::Profile profile;profile.id="conversion-profile";profile.candidate.expected_genesis=Scope().network.genesis.hex();profile.candidate.connection.credential={Authentication::SecureStore,"opaque-reference"};Take(store->SaveProfile(profile));store.reset();a::RecoverySession session(p);auto docs=Docs();Check(session.Protect(docs,Password),"seed protected metadata");throw std::runtime_error("test stop did not intercept actual conversion unlink");}
void MutateOther(const std::filesystem::path& p){sqlite3* db{};Check(sqlite3_open_v2(p.c_str(),&db,SQLITE_OPEN_READWRITE|SQLITE_OPEN_NOFOLLOW,nullptr)==SQLITE_OK,"owned fixture other copy opened");Check(sqlite3_exec(db,"UPDATE scopes SET display_name='Other metadata'",nullptr,nullptr,nullptr)==SQLITE_OK,"different metadata fixture");const auto docs=*a::EncodePublicSession({Docs(true),{}});sqlite3_stmt* q{};Check(sqlite3_prepare_v2(db,"UPDATE recovery SET revision=revision+1,public_documents=?",-1,&q,nullptr)==SQLITE_OK,"different recovery fixture prepared");Check(sqlite3_bind_text(q,1,docs.data(),int(docs.size()),SQLITE_TRANSIENT)==SQLITE_OK && sqlite3_step(q)==SQLITE_DONE,"different independent documents fixture");sqlite3_finalize(q);Check(sqlite3_close(db)==SQLITE_OK,"other copy fixture settled");}
void Validate(s::MetadataStore& store,bool other=false){Check(Take(store.Load(Scope()))==Metadata(other),"complete metadata/revisions/money/labels/layouts/freezes preserved");const auto w=Take(store.LoadWorkspace());Check(w.revision==1 && w.restore_documents && w.preferences.hide_balances,"workspace metadata preserved");const auto profile=Take(store.LoadProfile("conversion-profile"));Check(profile.revision==1 && profile.candidate.connection.credential.reference=="opaque-reference","profile reference preserved");const auto r=Take(store.LoadRecovery());auto session=a::DecodePublicSession(r.public_documents);Check(session && r.enabled && a::EncodePublicSession(*session)==a::EncodePublicSession({Docs(other),{}}),"two wallets/two transactions/exact coins/positions/revisions preserved");}
void Denied(const std::filesystem::path& p,bool tampered,bool conflicting_backup){const auto encrypted=std::filesystem::path(p.string()+".protected");const auto before=Bytes(p),cipher=Bytes(encrypted);a::RecoverySession session(p);a::DocumentRegistry docs;Check(session.Start() && session.Locked(),"interrupted startup locked");Check(!session.Unlock("wrong password",docs,true,true) && session.Locked() && docs.Documents().empty(),"wrong password never resolves or reveals either copy");Check(Bytes(p)==before && Bytes(encrypted)==cipher,"wrong password preserves both originals");if(tampered){Check(!session.Unlock(Password,docs,false,true) && !session.ConversionConflict(),"tampered encrypted data never falls back to plaintext");}else{Check(!session.Unlock(Password,docs) && session.ConversionConflict(),"different copies require deliberate authenticated resolution");if(conflicting_backup){auto owner=Take(s::MetadataStore::OpenProtected(p.string()+".conversion-backup",Password));Check(!session.Unlock(Password,docs,false,true) && session.Error().find("another instance")!=std::string::npos,"active backup owner blocks plaintext retirement");owner.reset();Check(!session.Unlock(Password,docs,false,true) && session.ConversionConflict(),"different existing backup cannot be overwritten");}}Check(Bytes(p)==before && Bytes(encrypted)==cipher && docs.Documents().empty(),"denied resolution preserves bytes and concealment");}
void Recover(const std::filesystem::path& p,bool different){const auto cipher=Bytes(p.string()+".protected"),other=Bytes(p);{a::RecoverySession session(p);a::DocumentRegistry docs;Check(session.Start() && session.Locked(),"normal restart sees protected file and locks");Check(session.Unlock(Password,docs,false,different),"authenticated conversion restart recovers");Check(session.Pending() && docs.Documents().empty(),"unlock does not automatically restore or execute");Check(session.Restore(docs) && a::EncodePublicSession({docs,{}})==a::EncodePublicSession({Docs(),{}}),"explicit offline restore chooses protected workspace");for(const auto& d:docs.Documents())Check(d.observation==a::ObservationState::Offline,"restored documents have no daemon authority");}Check(!std::filesystem::exists(p) && Bytes(p.string()+".protected")==cipher,"protected original unchanged and plaintext retired");auto store=Take(s::MetadataStore::OpenProtected(p,Password));Validate(*store);store.reset();if(different){const auto base=std::filesystem::path(p.string()+".conversion-backup");auto backup=Take(s::MetadataStore::OpenProtected(base,Password));Validate(*backup,true);auto raw=Take(backup->SealMemory("not a command"));Check(!raw.empty() && Bytes(base.string()+".protected").find("Other metadata")==std::string::npos,"other copy retained encrypted");}}
}
int main(int argc,char** argv){if(argc!=3)return 2;try{const std::string mode=argv[1];const std::filesystem::path p=argv[2];if(mode=="seed")Seed(p);else if(mode=="mutate")MutateOther(p);else if(mode=="identical")Recover(p,false);else if(mode=="different")Recover(p,true);else if(mode=="denied")Denied(p,false,false);else if(mode=="backup-conflict")Denied(p,false,true);else if(mode=="tampered")Denied(p,true,false);else return 2;std::cout<<"{\"passed\":true,\"checks\":"<<checks<<"}\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<" after "<<checks<<" checks\n";return 1;}}
